package com.vividflash.slayer;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.gameval.NpcID;

// Slayer masters with their base reward points per completed task. The point values feed the
// normal-streak recommendation math. They go unused for the separate-streak masters, which no rule
// can target. A master's stand-in (Aya, Achtryn, Steve, Kuradal) is matched by name as that master.
public enum SlayerMaster
{
    TURAEL("Turael", 0, "Aya"),
    SPRIA("Spria", 0),
    MAZCHNA("Mazchna", 6, "Achtryn"),
    VANNAKA("Vannaka", 8),
    CHAELDAR("Chaeldar", 10),
    KONAR("Konar quo Maten", 18),
    NIEVE("Nieve", 12, "Steve"),
    DURADEL("Duradel", 15, "Kuradal"),
    KRYSTILIA("Krystilia", 25, true),
    MORTIMER("Mortimer", 0, true);

    private static final SlayerMaster[] MASTERS = values();

    // Every NPC that offers an Assignment option, taken from the game cache, plus the multi-NPC
    // parents that turn into one, so the gate holds whether the id is the parent or the transformed
    // one. Quest, cutscene and follower copies of a master have no Assignment and are left out. Any
    // other id skips the name lookup.
    private static final Set<Integer> NPC_IDS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        NpcID.SLAYER_MASTER_1, NpcID.SLAYER_MASTER_1_TUREAL, NpcID.SLAYER_MASTER_1_AYA,
        NpcID.SLAYER_MASTER_9, NpcID.SLAYER_MASTER_9_ACTIVE,
        NpcID.SLAYER_MASTER_2, NpcID.SLAYER_MASTER_2_MAZCHNA,
        NpcID.SLAYER_MASTER_2_ACHTRYN, NpcID.SLAYER_MASTER_2_ACHTRYN_VIS,
        NpcID.SLAYER_MASTER_3,
        NpcID.SLAYER_MASTER_4,
        NpcID.SLAYER_MASTER_8,
        NpcID.SLAYER_MASTER_6, NpcID.SLAYER_MASTER_NIEVE, NpcID.SLAYER_MASTER_STEVE,
        NpcID.SLAYER_MASTER_5, NpcID.SLAYER_MASTER_5_DURADEL, NpcID.SLAYER_MASTER_5_KURADAL,
        NpcID.SLAYER_MASTER_7,
        NpcID.SLAYER_MASTER_MORTIMER, NpcID.SLAYER_MASTER_MORTIMER_VIS)));

    private final String displayName;
    private final int basePoints;
    // True for masters whose tasks run on their own streak (Krystilia's Wilderness streak,
    // Mortimer's own task count); taking one never consumes a normal-streak milestone, so the
    // wrong-master guards leave them alone on a rule task.
    private final boolean separateStreak;
    private final String[] extraNpcNames;

    SlayerMaster(String displayName, int basePoints, String... extraNpcNames)
    {
        this(displayName, basePoints, false, extraNpcNames);
    }

    SlayerMaster(String displayName, int basePoints, boolean separateStreak, String... extraNpcNames)
    {
        this.displayName = displayName;
        this.basePoints = basePoints;
        this.separateStreak = separateStreak;
        this.extraNpcNames = extraNpcNames;
    }

    public boolean hasSeparateStreak()
    {
        return separateStreak;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    // First word of the name, for the overlay's narrow column.
    public String getShortName()
    {
        int space = displayName.indexOf(' ');
        return space < 0 ? displayName : displayName.substring(0, space);
    }

    // Base points per task, adjusted for the elite diary bonuses the player has ticked in config.
    // Western Provinces takes Nieve from 12 to 15, and Kourend & Kebos takes Konar from 18 to 20.
    public int getBasePoints(boolean eliteWesternDiary, boolean eliteKourendDiary)
    {
        if (this == NIEVE && eliteWesternDiary)
        {
            return 15;
        }
        if (this == KONAR && eliteKourendDiary)
        {
            return 20;
        }
        return basePoints;
    }

    public boolean matchesNpcName(String npcName)
    {
        if (npcName == null)
        {
            return false;
        }
        if (displayName.equalsIgnoreCase(npcName))
        {
            return true;
        }
        for (String extra : extraNpcNames)
        {
            if (extra.equalsIgnoreCase(npcName))
            {
                return true;
            }
        }
        return false;
    }

    // Mortimer is matched by id, everyone else by name. An id outside the known master NPCs returns
    // null without a name lookup.
    public static SlayerMaster forNpc(NPC npc)
    {
        if (npc == null)
        {
            return null;
        }
        int id = npc.getId();
        if (!NPC_IDS.contains(id))
        {
            return null;
        }
        if (id == NpcID.SLAYER_MASTER_9)
        {
            // Spria's parent shows a Talk-to only quest Spria until Porcine of
            // Interest is done.
            NPCComposition shown = npc.getTransformedComposition();
            if (shown == null || shown.getId() != NpcID.SLAYER_MASTER_9_ACTIVE)
            {
                return null;
            }
        }
        if (id == NpcID.SLAYER_MASTER_MORTIMER || id == NpcID.SLAYER_MASTER_MORTIMER_VIS)
        {
            return MORTIMER;
        }
        return forNpc(npc.getName());
    }

    public static SlayerMaster forNpc(String npcName)
    {
        for (SlayerMaster master : MASTERS)
        {
            if (master.matchesNpcName(npcName))
            {
                return master;
            }
        }
        return null;
    }

    // Milestone multiplier for a given task number. Every 1000th task pays 50x base, 250th 35x,
    // 100th 25x, 50th 15x and 10th 5x, with the highest applicable one winning, otherwise 1x.
    public static int milestoneMultiplier(int taskNumber)
    {
        if (taskNumber % 1000 == 0)
        {
            return 50;
        }
        if (taskNumber % 250 == 0)
        {
            return 35;
        }
        if (taskNumber % 100 == 0)
        {
            return 25;
        }
        if (taskNumber % 50 == 0)
        {
            return 15;
        }
        if (taskNumber % 10 == 0)
        {
            return 5;
        }
        return 1;
    }

    // No points at all before the fifth task.
    public int getPointsForTask(int taskNumber, boolean eliteWesternDiary, boolean eliteKourendDiary)
    {
        if (taskNumber < 5)
        {
            return 0;
        }
        return getBasePoints(eliteWesternDiary, eliteKourendDiary) * milestoneMultiplier(taskNumber);
    }
}

