@Slf4j
@PluginDescriptor(
    name = "Better Slayer",
    description = "Mortimer Task Odds, Master Rules, Task Sorting, Nieve",
    tags = {"slayer", "nieve", "mortimer", "task", "boost"}
)
public class SlayerPlugin extends Plugin
{
    private static final String LAST_SEEN_VERSION_KEY = "lastSeenVersion";

    // The release the one-time notice below belongs to, not the packaged version.
    private static final String VERSION = "1.4";
    private static final String UPDATE_MESSAGE =
        "Patch " + VERSION + "; Mortimer shows where to go for each task, "
            + "Konar tells you the task area in chat";

    // Dark red for the one-time notice, legible on either chatbox background.
    private static final Color UPDATE_MESSAGE_COLOR = new Color(0x8B0000);

    @Inject
    private ConfigManager configManager;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private NieveInsteadOfSteveFeature nieveInsteadOfSteveFeature;

    @Inject
    private MasterRulesFeature masterRulesFeature;

    @Inject
    private TaskAreaFeature taskAreaFeature;

    @Inject
    private TaskSorterFeature taskSorterFeature;

    @Inject
    private TaskChoiceOddsFeature taskChoiceOddsFeature;

    private final List<Feature> features = new ArrayList<>();

    @Override
    protected void startUp()
    {
        features.add(nieveInsteadOfSteveFeature);
        features.add(masterRulesFeature);
        features.add(taskAreaFeature);
        features.add(taskSorterFeature);
        features.add(taskChoiceOddsFeature);
        if (log.isDebugEnabled())
        {
            log.debug("[state] startUp, features={}", features.size());
        }
        features.forEach(Feature::startUp);
    }

    @Override
    protected void shutDown()
    {
        log.debug("[state] shutDown");
        features.forEach(Feature::shutDown);
        features.clear();
    }

    // Shows the update notice once, on the first login after the version changes. The stored
    // version gates it, so no per-login flag is needed.
    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN
            || VERSION.equals(configManager.getConfiguration(SlayerConfig.GROUP, LAST_SEEN_VERSION_KEY)))
        {
            return;
        }

        if (log.isDebugEnabled())
        {
            log.debug("[update] notice shown for version {}", VERSION);
        }
        configManager.setConfiguration(SlayerConfig.GROUP, LAST_SEEN_VERSION_KEY, VERSION);
        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(new ChatMessageBuilder()
                .append(UPDATE_MESSAGE_COLOR, UPDATE_MESSAGE)
                .build())
            .build());
    }

    @Provides
    SlayerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(SlayerConfig.class);
    }
}

